face.layout_source:
// mono_synth.face: the panel for tap/examples/synths/mono_synth.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/synths/mono_synth.face --meta <graph>.cragmeta

face "Mono Synth" {
  row(gap = 10) {
    box "Filter" { knob.big "Cutoff" (cutoff) }
    box "Envelope" { adsr(attack, decay, sustain, release) }
    viz(grow = 1)
  }
  keys(note_on)
}
